window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-038c1ad869253b56"]={"versions": [{"id": "FIG-038c1ad869253b56", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR VFB-Komponentendiagramm (Software Component Description). Das Diagramm visualisiert die Port-Schnittstellenkonfiguration einer Atomic Software Component (<code>SeatHeatingControl</code>) im Kontext des Virtual Function Bus (VFB), speziell die Typisierung eines mode-abhängigen Empfängerports (<code>RPortPrototype</code>) über ein Sender-Receiver-Interface zur Modusüberwachung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Software-Komponente</strong>: <code>SeatHeatingControl</code> (UML-Komponentensymbol mit Symbol-Icon oben rechts).</li>\n<li><strong>Ports der Komponente</strong>:</li>\n<li><code>SeatSwitch</code>: R-Port (Sender-Receiver-Kommunikation, Dreieck nach innen zeigend).</li>\n<li><code>Setting</code>: P-Port (Sender-Receiver bzw. Client-Server / Provided-Port-Symbol).</li>\n<li><code>DialLED</code>: P-Port (Sender-Receiver-Kommunikation, Dreieck nach außen zeigend).</li>\n<li><code>HeatingElement</code>: R-Port (Client-Server / Required-Interface Socket-Symbol).</li>\n<li><code>PowerManagement</code>: P-Port (Sender-Receiver-Kommunikation, Dreieck nach außen zeigend).</li>\n<li><code>Calibration</code>: Kalibrierungsport (dreieckiges Calibration-Port-Symbol).</li>\n<li><code>nv</code>: Non-Volatile-Port (quadratisches Port-Symbol am unteren Rand, gefüllt dargestellt).</li>\n<li><code>ecuMode</code>: R-Port für Modus-Empfang (schwarzes Quadrat mit weißem Warndreieck-/Modus-Symbol).</li>\n<li><strong>Interface</strong>:</li>\n<li><code>&lt;&lt;Interface&gt;&gt; EcuMCurrentMode</code>: Sender-Receiver-Interface, typisiert durch das Attribut <code>ModeDeclarationGroups: ECUMMode currentMode</code>.</li>\n<li><strong>Beziehung</strong>:</li>\n<li>Gestrichelte Abhängigkeitslinie zwischen dem Port <code>ecuMode</code> und dem Interface <code>EcuMCurrentMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architektur- und Typisierungsansicht. Zur Laufzeit empfängt die Komponente <code>SeatHeatingControl</code> über den Port <code>ecuMode</code> Modusänderungen der <code>ModeDeclarationGroup</code> <code>ECUMMode</code> (ausgelöst durch den Mode-Manager <code>EcuM</code>), um ihr internes Betriebs- und Steuerungsverhalten synchron oder asynchron an den aktuellen ECU-Zustand anzupassen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Spezifikationsvorgabe aus AUTOSAR VFB, dass mode-abhängige Komponenten (<code>mode users</code>) Moduswechsel über R-Ports empfangen, die durch Sender-Receiver-Interfaces mit Bezug zu einer <code>ModeDeclarationGroup</code> typisiert sind. Entwickler müssen sicherstellen, dass die Modus-Deklarationen (<code>currentMode</code> vom Typ <code>ECUMMode</code>) konsistent zwischen dem Modus-Manager (z. B. ECU State Manager) und der Applikationskomponente modelliert werden.</p>"}, {"id": "FIG-0c2242daccaa8fa9", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR VFB-Komponentendiagramm (Software Component Description). Das Diagramm visualisiert die Port-Schnittstellenkonfiguration einer Atomic Software Component (<code>SeatHeatingControl</code>) im Kontext des Virtual Function Bus (VFB), speziell die Typisierung eines mode-abhängigen Empfängerports (<code>RPortPrototype</code>) über ein Sender-Receiver-Interface zur Modusüberwachung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Software-Komponente</strong>: <code>SeatHeatingControl</code> (UML-Komponentensymbol mit Symbol-Icon oben rechts).</li>\n<li><strong>Ports der Komponente</strong>:</li>\n<li><code>SeatSwitch</code>: R-Port (Sender-Receiver-Kommunikation, Dreieck nach innen zeigend).</li>\n<li><code>Setting</code>: P-Port (Sender-Receiver bzw. Client-Server / Provided-Port-Symbol).</li>\n<li><code>DialLED</code>: P-Port (Sender-Receiver-Kommunikation, Dreieck nach außen zeigend).</li>\n<li><code>HeatingElement</code>: R-Port (Client-Server / Required-Interface Socket-Symbol).</li>\n<li><code>PowerManagement</code>: P-Port (Sender-Receiver-Kommunikation, Dreieck nach außen zeigend).</li>\n<li><code>Calibration</code>: Kalibrierungsport (dreieckiges Calibration-Port-Symbol).</li>\n<li><code>nv</code>: Non-Volatile-Port (korrekt als nicht ausgefülltes Port-Kästchen mit internem NV-Symbol dargestellt).</li>\n<li><code>ecuMode</code>: R-Port für Modus-Empfang (schwarzes Quadrat mit weißem Warndreieck-/Modus-Symbol).</li>\n<li><strong>Interface</strong>:</li>\n<li><code>&lt;&lt;Interface&gt;&gt; EcuMCurrentMode</code>: Sender-Receiver-Interface, typisiert durch das Attribut <code>ModeDeclarationGroups: ECUMMode currentMode</code>.</li>\n<li><strong>Beziehung</strong>:</li>\n<li>Gestrichelte Abhängigkeitslinie zwischen dem Port <code>ecuMode</code> und dem Interface <code>EcuMCurrentMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architektur- und Typisierungsansicht. Zur Laufzeit empfängt die Komponente <code>SeatHeatingControl</code> über den Port <code>ecuMode</code> Modusänderungen der <code>ModeDeclarationGroup</code> <code>ECUMMode</code> (ausgelöst durch den Mode-Manager <code>EcuM</code>), um ihr internes Betriebs- und Steuerungsverhalten synchron oder asynchron an den aktuellen ECU-Zustand anzupassen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Spezifikationsvorgabe aus AUTOSAR VFB, dass mode-abhängige Komponenten (<code>mode users</code>) Moduswechsel über R-Ports empfangen, die durch Sender-Receiver-Interfaces mit Bezug zu einer <code>ModeDeclarationGroup</code> typisiert sind. Entwickler müssen sicherstellen, dass die Modus-Deklarationen (<code>currentMode</code> vom Typ <code>ECUMMode</code>) konsistent zwischen dem Modus-Manager (z. B. ECU State Manager) und der Applikationskomponente modelliert werden.</p>"}], "trans": [{"from": "FIG-038c1ad869253b56", "to": "FIG-0c2242daccaa8fa9", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Port <code>nv</code>: Die grafische Darstellung des Port-Symbols am unteren Rand der Software-Komponente wurde korrigiert (in der vorherigen Fassung war das quadratische Port-Icon fehlerhaft vollflächig schwarz gefüllt; nun korrekt als offenes Quadrat mit weißem Hintergrund und innenliegendem Non-Volatile-Symbol dargestellt).</li>\n</ul>"}]};
